// Command gauge is the menubar app: the dashboard runs in-process and
// appears as a popover under the status bar icon.
package main

import (
	"context"
	_ "embed"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"path/filepath"

	"github.com/abcdlsj/gauge/internal/app"

	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/events"
)

// trayIcon is the 22pt template glyph, generated by scripts/make_icons.py. The
// @2x bitmap is the one handed to Wails: it resizes the NSImage to the status
// bar height itself, so a retina-resolution source is what stays crisp.
//
//go:embed assets/tray-template@2x.png
var trayIcon []byte

func main() {
	logger := log.New(os.Stdout, "", log.LstdFlags|log.Lmsgprefix)

	dir, err := os.UserConfigDir()
	if err != nil {
		logger.Fatalf("config dir: %v", err)
	}
	dataDir := filepath.Join(dir, "Gauge")
	// One-time move from the pre-rename bundle so existing credentials survive.
	migrateLegacy(filepath.Join(dir, "Gemini Broad"), dataDir)
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		logger.Fatalf("create %s: %v", dataDir, err)
	}

	ctx := context.Background()
	a, err := app.New(ctx, app.Config{
		DBPath:         filepath.Join(dataDir, "quota.db"),
		KeyPath:        filepath.Join(dataDir, "gauge.key"),
		Logger:         logger,
		AllowEmbedding: true,
	})
	if err != nil {
		logger.Fatalf("start: %v", err)
	}
	a.Engine.Start(ctx)

	// The page reports the height of its painted panel; the shell resizes the
	// window to match so the content hugs all four edges with no dead space.
	// Anything past popoverMaxHeight does not grow the window: the list or the
	// settings form scrolls inside it (see .scroll-wrap in web/popover.css).
	const (
		popoverWidth = 372
		// initialPopoverHeight is only a starting point; the page reports the
		// real height as soon as it has painted.
		initialPopoverHeight = 640
		// popoverMinHeight keeps a nearly empty view (or a page that has not
		// painted yet) from collapsing the popover to a sliver.
		popoverMinHeight = 140
		// popoverMaxHeight is 900pt (the shortest display macOS still supports)
		// less the menu bar (24) and the Dock (96), so the popover always fits
		// between them without clipping its own footer.
		popoverMaxHeight = 780
	)
	var popover *application.WebviewWindow
	fittedHeight := initialPopoverHeight

	fitHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload struct {
			Height int `json:"height"`
		}
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "bad payload", http.StatusBadRequest)
			return
		}
		if payload.Height < popoverMinHeight {
			payload.Height = popoverMinHeight
		}
		if payload.Height > popoverMaxHeight {
			payload.Height = popoverMaxHeight
		}
		if popover != nil && payload.Height != fittedHeight {
			fittedHeight = payload.Height
			popover.SetSize(popoverWidth, payload.Height)
			logger.Printf("popover content height -> %d", payload.Height)
		}
		w.WriteHeader(http.StatusNoContent)
	})

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/api/ui/height" && r.Method == http.MethodPost {
			fitHandler.ServeHTTP(w, r)
			return
		}
		a.Handler.ServeHTTP(w, r)
	})

	ui := application.New(application.Options{
		Name: "Gauge",
		Assets: application.AssetOptions{
			Handler:        handler,
			DisableLogging: true,
		},
		Mac: application.MacOptions{
			// Menubar app: no Dock icon, no app switcher entry.
			ActivationPolicy: application.ActivationPolicyAccessory,
		},
	})

	popover = ui.Window.NewWithOptions(application.WebviewWindowOptions{
		Title:           "Gauge",
		Width:           popoverWidth,
		Height:          initialPopoverHeight,
		Frameless:       true,
		Hidden:          true,
		AlwaysOnTop:     true,
		DisableResize:   true,
		HideOnEscape:    true,
		HideOnFocusLost: true,
		URL:             "/popover",
	})

	popover.RegisterHook(events.Common.WindowClosing, func(e *application.WindowEvent) {
		popover.Hide()
		e.Cancel()
	})

	tray := ui.SystemTray.New()
	tray.SetTemplateIcon(trayIcon)
	tray.SetTooltip("Gauge")
	tray.AttachWindow(popover).WindowOffset(6)

	menu := ui.NewMenu()
	menu.Add("Refresh now").OnClick(func(*application.Context) {
		go a.Engine.RefreshAll(ctx)
	})
	menu.AddSeparator()
	menu.Add("Quit").OnClick(func(*application.Context) {
		ui.Quit()
	})
	tray.SetMenu(menu)

	ui.OnShutdown(func() { _ = a.Close() })

	if err := ui.Run(); err != nil {
		logger.Fatalf("run: %v", err)
	}
}

// migrateLegacy copies the database and key from the old bundle directory once.
func migrateLegacy(oldDir, newDir string) {
	if _, err := os.Stat(newDir); err == nil {
		return
	}
	if _, err := os.Stat(oldDir); err != nil {
		return
	}
	if err := os.MkdirAll(newDir, 0o700); err != nil {
		return
	}
	pairs := [][2]string{
		{"quota.db", "quota.db"},
		{"quota.db-wal", "quota.db-wal"},
		{"quota.db-shm", "quota.db-shm"},
		{"gpanel.key", "gauge.key"},
	}
	for _, p := range pairs {
		raw, err := os.ReadFile(filepath.Join(oldDir, p[0]))
		if err != nil {
			continue
		}
		_ = os.WriteFile(filepath.Join(newDir, p[1]), raw, 0o600)
	}
}
